// Template rendering: {{contact.name}}, {{case.code}}, {{quote.lines_table}}, {{today}}...
// Values are HTML-escaped; only values wrapped in Raw (generated by our own code) are inserted as markup.

export class Raw {
  constructor(public readonly html: string) {}
}

export const escapeHtml = (s: string) =>
  s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");

export type TemplateContext = Record<string, unknown>;

function lookup(ctx: TemplateContext, path: string): unknown {
  let cur: unknown = ctx;
  for (const part of path.split(".")) {
    if (cur && typeof cur === "object" && !(cur instanceof Raw) && Object.prototype.hasOwnProperty.call(cur, part)) {
      cur = (cur as Record<string, unknown>)[part];
    } else {
      return undefined;
    }
  }
  return cur;
}

// The editor wraps variables in <span data-var="x">{{x}}</span> chips; the markup is dropped before rendering.
const CHIP = /<span[^>]*\sdata-var="([a-zA-Z0-9_.]+)"[^>]*>[\s\S]*?<\/span>/g;

export function renderTemplate(body: string, ctx: TemplateContext) {
  const unknown = new Set<string>();
  const html = body
    .replace(CHIP, (_m, key: string) => `{{${key}}}`)
    .replace(/\{\{\s*([a-zA-Z0-9_.]+)\s*\}\}/g, (_m, path: string) => {
      const v = lookup(ctx, path);
      if (v === undefined) {
        unknown.add(path);
        return "";
      }
      if (v instanceof Raw) return v.html;
      return v === null ? "" : escapeHtml(String(v)).replace(/\n/g, "<br>");
    });
  return { html, unknown: [...unknown] };
}

// Turns plain {{variables}} into editor chips (used when loading a template into the editor).
// Existing chips are protected first so they are never wrapped twice.
export function chipifyVariables(html: string) {
  const saved: string[] = [];
  const protectedHtml = html.replace(CHIP, (m) => {
    saved.push(m);
    return `\u0000${saved.length - 1}\u0000`;
  });
  return protectedHtml
    .replace(/\{\{\s*([a-zA-Z0-9_.]+)\s*\}\}/g, (_m, key: string) => `<span data-var="${key}">{{${key}}}</span>`)
    .replace(/\u0000(\d+)\u0000/g, (_m, i: string) => saved[Number(i)]);
}
